// Experimental (2026-11-07), redesigned same day per the owner's direct feedback: the structured
// (Executive Summary/KPIs/sections/work-by-date/upcoming-work) format must be generated ONCE, at
// drafting time ("AI Summary"), and saved as ordinary, editable report content_text — never
// re-generated by an AI call every time someone clicks "HTML"/"PDF". Export stays "dumb": it just
// renders whatever text is already saved, exactly like every other report.
//
// This file is the round-trip between that JSON shape (ai-router's STRUCTURED_CLIENT_REPORT task
// output — taskRegistry.ts's validateStructuredClientReportOutput) and a plain, line-based text
// format that:
//  - is what gets written into the draft editor and saved as a report_content_versions row, so it
//    stays hand-editable like any other draft text before Save version/Approve final;
//  - can be split back into sections by pdfExport.ts's existing parseReportContentIntoParagraphs
//    (blank-line-separated blocks, first line is the heading) — this format follows that same
//    general shape, just with new heading names (STRUCTURED_REPORT_HEADINGS below) instead of the
//    older REPORT_SECTION_HEADINGS ones;
//  - round-trips back into the full JSON shape via parseStructuredReportText, used by
//    reportHtmlExport.ts at export time to decide whether a given saved report is in this new
//    shape (render with the rich branded template) or the older one (render with the original
//    plain template) — detected purely from content_text itself, never a separate flag/column, so
//    no schema change and no migration for reports saved before this existed.
//
// Kept dependency-free (no import of pdfExport.ts/ComparisonDisplay.tsx) so both
// ReportDraftWorkspace.tsx (writes this format after an AI Summary call) and reportHtmlExport.ts
// (reads it back at export time) can import it without adding to either file's existing import
// graph — reportHtmlExport.ts already imports pdfExport.ts, and ComparisonDisplay.tsx already
// imports reportHtmlExport.ts, so a file sitting below all three avoids any risk of a cycle.

export const STRUCTURED_REPORT_HEADINGS = {
  executiveSummary: 'Executive Summary',
  workByDate: 'Work by Date',
  upcomingWork: 'Upcoming Work',
} as const;

export interface StructuredReportTextShape {
  executive_summary: {
    paragraph: string;
    kpis: { label: string; value: string; note: string }[];
    caveat: string;
  };
  // A block/upcoming-work-item's body is an ARRAY of separate points (changed 2026-11-07 per
  // direct owner feedback: several distinct points joined into one string read as an unreadable
  // run-on line instead of stacked, scannable bullets) — see this file's serializeBlock/
  // parseTitleBodyBlocks below for how each array item becomes its own "- " line in the saved
  // text, and reportHtmlExport.ts's buildStructuredClientReportHtml for how it renders (a <ul> of
  // bullets for 2+ items, a plain paragraph for exactly 1).
  sections: { heading: string; blocks: { title: string; body: string[] }[] }[];
  work_by_date: { date: string; summary: string }[];
  upcoming_work: { title: string; body: string[] }[];
}

// Every free-text field below can, in principle, come back from the AI with an embedded newline
// (a multi-sentence paragraph, say) — this format is line-based (one block/KPI/date-row per
// line), so any embedded newline is flattened to a single space before it's written, keeping the
// text round-trippable. Nothing here ever runs on untrusted HTML, so no escaping is needed (that
// happens downstream, once, in reportHtmlExport.ts's own escapeHtml).
function flatten(value: string): string {
  return value.replace(/\s*\n\s*/g, ' ').trim();
}

function serializeKpiLine(kpi: { label: string; value: string; note: string }): string {
  return `KPI: ${flatten(kpi.label)} — ${flatten(kpi.value)}${kpi.note.trim() ? ` (${flatten(kpi.note)})` : ''}`;
}

const KPI_LINE_RE = /^KPI:\s*(.+?)\s*—\s*(.+?)(?:\s*\((.*)\))?$/;

function parseKpiLine(line: string): { label: string; value: string; note: string } | null {
  const match = KPI_LINE_RE.exec(line.trim());
  if (!match) return null;
  return { label: match[1].trim(), value: match[2].trim(), note: (match[3] || '').trim() };
}

// One block/upcoming-work-item becomes a title line ending in ":" followed by one "- " line per
// body item — e.g.:
//   Stories:
//   - Posted 12 stories reaching 4500 accounts.
//   - Scheduled 3 posts for next week.
// Always this two-or-more-line shape, even for a single body item, so parseTitleBodyBlocks below
// has exactly one parsing rule to apply (a line is either a new block's title or a "- " item of
// the current one) rather than having to also recognize an old single-line "Title: body" form.
function serializeBlock(block: { title: string; body: string[] }): string {
  const titleLine = `${flatten(block.title)}:`;
  const bodyLines = block.body.map((item) => `- ${flatten(item)}`);
  return [titleLine, ...bodyLines].join('\n');
}

export function serializeStructuredReportText(report: StructuredReportTextShape): string {
  const sections: string[] = [];

  const execLines = [flatten(report.executive_summary.paragraph)];
  report.executive_summary.kpis.forEach((kpi) => execLines.push(serializeKpiLine(kpi)));
  if (report.executive_summary.caveat.trim()) execLines.push(`Caveat: ${flatten(report.executive_summary.caveat)}`);
  sections.push(`${STRUCTURED_REPORT_HEADINGS.executiveSummary}\n${execLines.filter(Boolean).join('\n')}`);

  report.sections.forEach((section) => {
    const body = section.blocks
      .filter((block) => block.body.length > 0)
      .map(serializeBlock)
      .join('\n');
    if (body) sections.push(`${section.heading}\n${body}`);
  });

  if (report.work_by_date.length) {
    sections.push(`${STRUCTURED_REPORT_HEADINGS.workByDate}\n${report.work_by_date
      .map((row) => `${flatten(row.date)} — ${flatten(row.summary)}`)
      .join('\n')}`);
  }

  if (report.upcoming_work.length) {
    sections.push(`${STRUCTURED_REPORT_HEADINGS.upcomingWork}\n${report.upcoming_work
      .filter((item) => item.body.length > 0)
      .map(serializeBlock)
      .join('\n')}`);
  }

  return sections.join('\n\n');
}

// Same blank-line-separated-blocks split as pdfExport.ts's parseReportContentIntoParagraphs —
// duplicated as three lines rather than imported, see this file's header comment for why.
function splitIntoSections(text: string): { heading: string; body: string }[] {
  return text
    .split(/\n\s*\n/)
    .map((block) => block.trim())
    .filter(Boolean)
    .map((block) => {
      const lines = block.split('\n');
      return { heading: lines[0].trim(), body: lines.slice(1).join('\n').trim() };
    });
}

// Reverses serializeBlock above: a line starting with "- " is a body item of the block currently
// being built; any other non-empty line starts a new block (its trailing ":", if present, is
// dropped — serializeBlock always writes one, but this stays tolerant of a hand-edited draft that
// doesn't). A "- " line encountered before any title line is a parsing artifact with nothing to
// attach to and is dropped; a block that ends up with zero body items (also only possible from a
// hand-edited draft) is dropped too, same as the AI-output validator never emits an empty block.
function parseTitleBodyBlocks(body: string): { title: string; body: string[] }[] {
  const blocks: { title: string; body: string[] }[] = [];
  body
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .forEach((line) => {
      if (line.startsWith('- ')) {
        const item = line.slice(2).trim();
        if (item && blocks.length) blocks[blocks.length - 1].body.push(item);
        return;
      }
      const title = line.endsWith(':') ? line.slice(0, -1).trim() : line;
      blocks.push({ title, body: [] });
    });
  return blocks.filter((block) => block.body.length > 0);
}

// Returns null for any report NOT in this shape (every report saved before this feature existed,
// or one whose author never ran the new AI Summary on it) — detected solely by its first section's
// heading being exactly STRUCTURED_REPORT_HEADINGS.executiveSummary, so an old report is never
// misread as this new shape by coincidence (a hand-written report would have to literally start
// with that exact English heading).
export function parseStructuredReportText(contentText: string): StructuredReportTextShape | null {
  const sections = splitIntoSections(contentText);
  if (!sections.length || sections[0].heading !== STRUCTURED_REPORT_HEADINGS.executiveSummary) return null;

  const [execSection, ...rest] = sections;
  const kpis: { label: string; value: string; note: string }[] = [];
  let caveat = '';
  const paragraphLines: string[] = [];
  execSection.body.split('\n').map((line) => line.trim()).filter(Boolean).forEach((line) => {
    const kpi = parseKpiLine(line);
    if (kpi) { kpis.push(kpi); return; }
    if (line.startsWith('Caveat:')) { caveat = line.slice('Caveat:'.length).trim(); return; }
    paragraphLines.push(line);
  });

  const workByDateSection = rest.find((s) => s.heading === STRUCTURED_REPORT_HEADINGS.workByDate);
  const upcomingWorkSection = rest.find((s) => s.heading === STRUCTURED_REPORT_HEADINGS.upcomingWork);
  const topicSections = rest.filter(
    (s) => s.heading !== STRUCTURED_REPORT_HEADINGS.workByDate && s.heading !== STRUCTURED_REPORT_HEADINGS.upcomingWork
  );

  const workByDate = workByDateSection
    ? workByDateSection.body.split('\n').map((line) => line.trim()).filter(Boolean).map((line) => {
        const dashIndex = line.indexOf(' — ');
        return dashIndex === -1 ? { date: line, summary: '' } : { date: line.slice(0, dashIndex).trim(), summary: line.slice(dashIndex + 3).trim() };
      })
    : [];

  return {
    executive_summary: { paragraph: paragraphLines.join(' ').trim(), kpis, caveat },
    sections: topicSections.map((s) => ({ heading: s.heading, blocks: parseTitleBodyBlocks(s.body) })),
    work_by_date: workByDate,
    upcoming_work: upcomingWorkSection ? parseTitleBodyBlocks(upcomingWorkSection.body) : [],
  };
}
